def solve(nums: list[int], k: int) -> int:
    if k <= 0:
        return 0

    first_seen = {0: 0}
    prefix_mod = 0
    max_len = 0

    for i, num in enumerate(nums, start=1):
        prefix_mod = (prefix_mod + num) % k
        if prefix_mod in first_seen:
            max_len = max(max_len, i - first_seen[prefix_mod])
        else:
            first_seen[prefix_mod] = i

    return max_len
